INSERT INTO exam_questions (subject, grade, question_type, question_text, options, answer, explanation, difficulty, topic)
VALUES
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'คำว่า ''ทศวรรษ'' หมายถึงช่วงเวลากี่ปี', '["10 ปี","100 ปี","1,000 ปี","50 ปี"]'::jsonb, '0'::jsonb, 'ทศวรรษ หมายถึง รอบระยะเวลา 10 ปี (ทศ = 10, วรรษ = ปี)', 'easy', '[ส 4.1 ป.4/1] ช่วงเวลาทางประวัติศาสตร์ (ทศวรรษ)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'คำว่า ''ศตวรรษ'' หมายถึงช่วงเวลากี่ปี', '["100 ปี","10 ปี","500 ปี","1,000 ปี"]'::jsonb, '0'::jsonb, 'ศตวรรษ หมายถึง รอบระยะเวลา 100 ปี (ศต = 100)', 'easy', '[ส 4.1 ป.4/1] ช่วงเวลาทางประวัติศาสตร์ (ศตวรรษ)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'คำว่า ''สหัสวรรษ'' หมายถึงช่วงเวลากี่ปี', '["1,000 ปี","100 ปี","10 ปี","10,000 ปี"]'::jsonb, '0'::jsonb, 'สหัสวรรษ หมายถึง รอบระยะเวลา 1,000 ปี (สหัส = 1,000)', 'easy', '[ส 4.1 ป.4/1] ช่วงเวลาทางประวัติศาสตร์ (สหัสวรรษ)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เกณฑ์สำคัญที่สุดที่นักประวัติศาสตร์ใช้แบ่งระหว่าง ''ยุคก่อนประวัติศาสตร์'' กับ ''ยุคประวัติศาสตร์'' คือข้อใด', '["การประดิษฐ์และการใช้ตัวอักษรบันทึกเรื่องราว","การสร้างเมืองหลวงขนาดใหญ่","การรู้จักใช้ไฟทำอาหาร","การทำสงคราม"]'::jsonb, '0'::jsonb, 'มนุษยชาติเข้าสู่ยุคประวัติศาสตร์เมื่อรู้จักคิดค้นตัวอักษรและบันทึกข้อความ หากยังไม่มีตัวอักษรจะจัดเป็นยุคก่อนประวัติศาสตร์', 'easy', '[ส 4.1 ป.4/2] ยุคก่อนประวัติศาสตร์และยุคประวัติศาสตร์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'หลักฐานในข้อใดจัดเป็น ''หลักฐานที่เป็นลายลักษณ์อักษร''', '["ศิลาจารึกและจดหมายเหตุ","หม้อดินเผาบ้านเชียง","ขวานหินขัด","โครงกระดูกมนุษย์โบราณ"]'::jsonb, '0'::jsonb, 'ศิลาจารึก จดหมายเหตุ พงศาวดาร ใบลาน มีการจารึกตัวหนังสือ จึงเป็นหลักฐานที่เป็นลายลักษณ์อักษร', 'easy', '[ส 4.1 ป.4/3] ประเภทของหลักฐานทางประวัติศาสตร์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'แหล่งโบราณคดี ''บ้านเชียง'' มีชื่อเสียงระดับโลกเรื่องภาชนะดินเผาลายเขียนสีแดง ตั้งอยู่ในจังหวัดใดของไทย', '["จังหวัดอุดรธานี","จังหวัดขอนแก่น","จังหวัดนครราชสีมา","จังหวัดเชียงใหม่"]'::jsonb, '0'::jsonb, 'แหล่งโบราณคดีบ้านเชียงเป็นมรดกโลกทางวัฒนธรรม ตั้งอยู่ที่อำเภอหนองหาน จังหวัดอุดรธานี', 'easy', '[ส 4.2 ป.4/1] แหล่งโบราณคดีบ้านเชียง'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', '''ธรรมจักรศิลาและกวางหมอบ'' เป็นโบราณวัตถุชิ้นเอกของอาณาจักรโบราณใดในดินแดนไทย', '["อาณาจักรทวารวดี","อาณาจักรศรีวิชัย","อาณาจักรสุโขทัย","อาณาจักรล้านนา"]'::jsonb, '0'::jsonb, 'ธรรมจักรศิลาพร้อมกวางหมอบสะท้อนอิทธิพลพระพุทธศาสนานิกายเถรวาทในอาณาจักรทวารวดี (ศูนย์กลางแถบนครปฐม)', 'easy', '[ส 4.2 ป.4/2] อาณาจักรทวารวดี'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พระบรมธาตุไชยา และรูปหล่อพระโพธิสัตว์อวโลกิเตศวร เป็นหลักฐานทางประวัติศาสตร์ของอาณาจักรใดทางภาคใต้', '["อาณาจักรศรีวิชัย","อาณาจักรทวารวดี","อาณาจักรหริภุญชัย","อาณาจักรละโว้"]'::jsonb, '0'::jsonb, 'อาณาจักรศรีวิชัยมีศูนย์กลางสำคัญอยู่ที่อำเภอไชยา จังหวัดสุราษฎร์ธานี นับถือพระพุทธศาสนานิกายมหายาน', 'easy', '[ส 4.2 ป.4/2] อาณาจักรศรีวิชัย'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ปฐมกษัตริย์ผู้ทรงสถาปนาอาณาจักรสุโขทัยและราชวงศ์พระร่วง คือพระมหากษัตริย์พระองค์ใด', '["พ่อขุนศรีอินทราทิตย์","พ่อขุนรามคำแหงมหาราช","พ่อขุนบางกลางหาว","พระมหาธรรมราชาที่ 1 (ลิไทย)"]'::jsonb, '0'::jsonb, 'พ่อขุนบางกลางหาวได้รับสถาปนาพระนามว่า ''พ่อขุนศรีอินทราทิตย์'' เป็นปฐมกษัตริย์แห่งราชวงศ์พระร่วง อาณาจักรสุโขทัย', 'easy', '[ส 4.3 ป.4/1] ปฐมกษัตริย์แห่งอาณาจักรสุโขทัย'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พระมหากษัตริย์พระองค์ใดทรงประดิษฐ์ ''ลายสือไทย'' ซึ่งเป็นต้นกำเนิดของอักษรไทยในปัจจุบัน', '["พ่อขุนรามคำแหงมหาราช","พ่อขุนศรีอินทราทิตย์","สมเด็จพระนเรศวรมหาราช","สมเด็จพระนารายณ์มหาราช"]'::jsonb, '0'::jsonb, 'พ่อขุนรามคำแหงมหาราชทรงประดิษฐ์ลายสือไทยขึ้นเมื่อ พ.ศ. 1826 โดยดัดแปลงมาจากอักษรขอมและอักษรมอญโบราณ', 'easy', '[ส 4.3 ป.4/2] การประดิษฐ์อักษรไทย'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ข้อความในศิลาจารึกที่ว่า ''ใครจักใคร่ค้าช้าง ค้า ใครจักใคร่ค้าม้า ค้า'' แสดงถึงลักษณะทางเศรษฐกิจแบบใดในสมัยสุโขทัย', '["การค้าขายแบบเสรี ไม่เก็บภาษีผ่านด่าน (จังกอบ)","การผูกขาดการค้าโดยกษัตริย์","การห้ามราษฎรค้าขายสัตว์เลี้ยง","การค้าขายเฉพาะกับชาวต่างชาติ"]'::jsonb, '0'::jsonb, 'ข้อความนี้แสดงถึงนโยบายการค้าแบบเสรี ราษฎรสามารถค้าขายได้อย่างอิสระโดยไม่ต้องเสียภาษีจังกอบ (ภาษีผ่านด่าน)', 'easy', '[ส 4.3 ป.4/2] การค้าในสมัยสุโขทัย'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เครื่องปั้นดินเผาเคลือบที่เป็นสินค้าส่งออกสำคัญและสร้างชื่อเสียงให้อาณาจักรสุโขทัย เรียกว่าอะไร', '["เครื่องสังคโลก","เครื่องเบญจรงค์","เครื่องลายคราม","หม้อดินเผาลายเขียนสี"]'::jsonb, '0'::jsonb, 'เครื่องสังคโลก เป็นสินค้าส่งออกเลื่องชื่อของสุโขทัยที่ผลิตจากเตาทุเรียง ส่งออกไปขายยังดินแดนต่างๆ เช่น ญี่ปุ่น อินโดนีเซีย ฟิลิปปินส์', 'easy', '[ส 4.3 ป.4/2] เครื่องปั้นดินเผาสุโขทัย'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'รูปแบบการปกครองของสุโขทัยในยุคต้นที่มีความใกล้ชิด อบอุ่น เปรียบเสมือนครอบครัว เรียกว่ารูปแบบใด', '["การปกครองแบบพ่อปกครองลูก","การปกครองแบบสมบูรณาญาสิทธิราชย์","การปกครองแบบเทวราชา","การปกครองแบบประชาธิปไตย"]'::jsonb, '0'::jsonb, 'สุโขทัยตอนต้นใช้การปกครองแบบ ''พ่อปกครองลูก'' กษัตริย์ทรงดูแลทุกข์สุขของราษฎรดั่งพ่อดูแลบุตร มีการแขวนกระดิ่งให้ราษฎรมาร้องทุกข์', 'easy', '[ส 4.3 ป.4/2] การปกครองสมัยสุโขทัยตอนต้น'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'วรรณกรรมทางพระพุทธศาสนาเรื่องแรกของไทยที่ทรงพระราชนิพนธ์โดยพระมหาธรรมราชาที่ 1 (ลิไทย) คือเรื่องใด', '["ไตรภูมิพระร่วง (เตภูมิกถา)","มหาชาติคำหลวง","ลิลิตพระลอ","ขุนช้างขุนแผน"]'::jsonb, '0'::jsonb, 'ไตรภูมิพระร่วง (เตภูมิกถา) เป็นวรรณคดีพุทธศาสนาที่สอนเรื่องบาปบุญคุณโทษ การเวียนว่ายตายเกิดในภพภูมิต่างๆ', 'easy', '[ส 4.3 ป.4/3] พระมหาธรรมราชาที่ 1 (ลิไทย)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พระยาพิชัยดาบหัก เป็นวีรบุรุษคนสำคัญที่มีความกล้าหาญและจงรักภักดีต่อพระมหากษัตริย์พระองค์ใด', '["สมเด็จพระเจ้าตากสินมหาราช","สมเด็จพระนเรศวรมหาราช","พ่อขุนรามคำแหงมหาราช","พระบาทสมเด็จพระพุทธยอดฟ้าจุฬาโลกมหาราช"]'::jsonb, '0'::jsonb, 'พระยาพิชัยดาบหัก (ทองดี ฟันขาว) เป็นแม่ทัพคู่พระทัยของสมเด็จพระเจ้าตากสินมหาราช ที่สู้รบกับข้าศึกอย่างกล้าหาญจนดาบหักไปหนึ่งเล่ม', 'easy', '[ส 4.3 ป.4/3] วีรบุรุษไทย (พระยาพิชัยดาบหัก)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พุทธศักราช 2567 จัดอยู่ในพุทธศตวรรษที่เท่าใด', '["พุทธศตวรรษที่ 26","พุทธศตวรรษที่ 25","พุทธศตวรรษที่ 24","พุทธศตวรรษที่ 27"]'::jsonb, '0'::jsonb, 'พุทธศตวรรษที่ 26 เริ่มต้นตั้งแต่ พ.ศ. 2501 ถึง พ.ศ. 2600 ดังนั้น พ.ศ. 2567 จึงอยู่ในพุทธศตวรรษที่ 26', 'medium', '[ส 4.1 ป.4/1] การนับศตวรรษในประวัติศาสตร์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'คริสต์ศตวรรษที่ 21 (ศตวรรษปัจจุบัน) เริ่มต้นและสิ้นสุดในปี ค.ศ. ใด', '["ค.ศ. 2001 - ค.ศ. 2100","ค.ศ. 2000 - ค.ศ. 2099","ค.ศ. 1901 - ค.ศ. 2000","ค.ศ. 2101 - ค.ศ. 2200"]'::jsonb, '0'::jsonb, 'คริสต์ศตวรรษที่ 21 เริ่มนับตั้งแต่ ค.ศ. 2001 ถึง ค.ศ. 2100', 'medium', '[ส 4.1 ป.4/1] การนับคริสต์ศตวรรษ'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ความก้าวหน้าที่สำคัญที่สุดของมนุษย์ใน ''ยุคหินใหม่'' ที่แตกต่างจากยุคหินเก่าอย่างสิ้นเชิงคือข้อใด', '["การรู้จักเพาะปลูก เลี้ยงสัตว์ และตั้งถิ่นฐานเป็นหลักแหล่ง","การประดิษฐ์เครื่องบิน","การใช้ตัวอักษรจดบันทึก","การเดินทางด้วยเรือกลไฟ"]'::jsonb, '0'::jsonb, 'ยุคหินเก่ามนุษย์เร่ร่อนเก็บของป่าล่าสัตว์ ส่วนยุคหินใหม่มนุษย์เริ่มทำการเกษตร เพาะปลูก เลี้ยงสัตว์ และสร้างชุมชนถาวร', 'medium', '[ส 4.1 ป.4/2] ยุคหินเก่า vs ยุคหินใหม่'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'โลหะชนิดแรกที่มนุษย์โบราณนำมาผสมกันจนเกิดเป็น ''สำริด'' (Bronze) คือโลหะคู่ใด', '["ทองแดง ผสม ดีบุก","เหล็ก ผสม สังกะสี","ทองคำ ผสม เงิน","อะลูมิเนียม ผสม ตะกั่ว"]'::jsonb, '0'::jsonb, 'สำริดเป็นโลหะผสมระหว่างทองแดง (Copper) กับดีบุก (Tin) ทำให้ได้โลหะที่มีความแข็งแรงกว่าทองแดงบริสุทธิ์', 'medium', '[ส 4.1 ป.4/2] ยุคสำริด'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ข้อใดจัดเป็น ''หลักฐานชั้นต้น'' (หลักฐานปฐมภูมิ) ทางประวัติศาสตร์ทั้งหมด', '["ศิลาจารึกหลักที่ 1, บันทึกจดหมายเหตุของบาทหลวงตาชาร์ด","หนังสือเรียนประวัติศาสตร์ ป.4, สารคดีโทรทัศน์","ภาพยนตร์อิงประวัติศาสตร์, นิยายอิงประวัติศาสตร์","บทความวิจัยที่เขียนในปัจจุบัน, อนุสาวรีย์สร้างใหม่"]'::jsonb, '0'::jsonb, 'หลักฐานชั้นต้นคือหลักฐานที่ถูกบันทึกหรือสร้างขึ้นโดยบุคคลที่อยู่ในเหตุการณ์นั้นจริง เช่น ศิลาจารึก เอกสารสนธิสัญญา บันทึกส่วนตัวร่วมสมัย', 'medium', '[ส 4.1 ป.4/3] หลักฐานชั้นต้น (Primary Source)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เหตุใดหนังสือเรียนประวัติศาสตร์หรือบทความวิเคราะห์ประวัติศาสตร์จึงจัดเป็น ''หลักฐานชั้นรอง''', '["เพราะเรียบเรียงขึ้นในภายหลังโดยอาศัยข้อมูลจากหลักฐานชั้นต้น","เพราะไม่มีความน่าเชื่อถือเลย","เพราะไม่มีรูปภาพประกอบ","เพราะเขียนขึ้นโดยคนต่างชาติ"]'::jsonb, '0'::jsonb, 'หลักฐานชั้นรองคือเอกสารหรือผลงานที่นักประวัติศาสตร์รุ่นหลังค้นคว้าและเรียบเรียงขึ้นโดยอาศัยหลักฐานชั้นต้นเป็นข้อมูลอ้างอิง', 'medium', '[ส 4.1 ป.4/3] หลักฐานชั้นรอง (Secondary Source)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'แหล่งโบราณคดี ''ถ้ำผีแมน'' จังหวัดแม่ฮ่องสอน พบหลักฐานสำคัญเกี่ยวกับมนุษย์ยุคก่อนประวัติศาสตร์ในเรื่องใด', '["โลงไม้รูปเรือหรือโลงผีแมนและเมล็ดพืชโบราณ","พระพุทธรูปทองคำ","กำแพงอิฐขนาดใหญ่","เรือสำเภาโบราณ"]'::jsonb, '0'::jsonb, 'ถ้ำผีแมนเป็นแหล่งโบราณคดียุคหินและโลหะที่มีการค้นพบโลงศพทำจากท่อนซุง (โลงไม้ผีแมน) และร่องรอยการเก็บเกี่ยวพืชผล', 'medium', '[ส 4.2 ป.4/1] แหล่งโบราณคดีถ้ำผีแมน'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ปฐมกษัตริย์สตรีผู้สร้างและปกครองอาณาจักรหริภุญชัย (ปัจจุบันคือจังหวัดลำพูน) คือใคร', '["พระนางจามเทวี","พระสุพรรณกัลยา","ท้าวสุรนารี","สมเด็จพระศรีสุริโยทัย"]'::jsonb, '0'::jsonb, 'พระนางจามเทวี เจ้าหญิงจากเมืองละโว้ เสด็จขึ้นไปครองเมืองหริภุญชัย (ลำพูน) และเผยแผ่พระพุทธศาสนาและศิลปวิทยาการ', 'medium', '[ส 4.2 ป.4/2] อาณาจักรหริภุญชัย'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พระปรางค์สามยอด ในจังหวัดลพบุรี เป็นโบราณสถานสำคัญที่สะท้อนถึงอิทธิพลของอารยธรรมใดในอาณาจักรละโว้', '["อิทธิพลศิลปวัฒนธรรมขอม (เขมรโบราณ)","อิทธิพลศิลปวัฒนธรรมจีน","อิทธิพลศิลปวัฒนธรรมพม่า","อิทธิพลศิลปวัฒนธรรมกรีก"]'::jsonb, '0'::jsonb, 'พระปรางค์สามยอดเป็นปราสาทหินศิลปะขอมแบบบายน สะท้อนถึงการรับอิทธิพลทางศาสนาและศิลปะจากอาณาจักรขอมโบราณ', 'medium', '[ส 4.2 ป.4/2] อาณาจักรละโว้'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'อาณาจักรตามพรลิงก์ในอดีต ตั้งอยู่บริเวณศูนย์กลางของจังหวัดใดในปัจจุบัน และมีโบราณสถานสำคัญคืออะไร', '["จังหวัดนครศรีธรรมราช - พระบรมธาตุเจดีย์","จังหวัดภูเก็ต - แหลมพรหมเทพ","จังหวัดสุราษฎร์ธานี - เขาสก","จังหวัดสงขลา - สะพานติณสูลานนท์"]'::jsonb, '0'::jsonb, 'อาณาจักรตามพรลิงก์เป็นศูนย์กลางการค้าและพระพุทธศาสนาทางภาคใต้ บริเวณจังหวัดนครศรีธรรมราช มีพระบรมธาตุเจดีย์เป็นศูนย์รวมศรัทธา', 'medium', '[ส 4.2 ป.4/2] อาณาจักรตามพรลิงก์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พ่อขุนบางกลางหาวทรงร่วมมือกับผู้นำท่านใดในการขับไล่ขอมสบาดโขลญลำพงเพื่อปลดปล่อยสุโขทัยให้เป็นอิสระ', '["พ่อขุนผาเมือง (เจ้าเมืองราด)","พ่อขุนศรีอินทราทิตย์","พ่อขุนรามคำแหง","พญามังราย"]'::jsonb, '0'::jsonb, 'พ่อขุนบางกลางหาวและพ่อขุนผาเมืองร่วมมือกันยกทัพเข้าตีกองทัพขอมสบาดโขลญลำพงจนได้รับชัยชนะ และสถาปนากรุงสุโขทัย', 'medium', '[ส 4.3 ป.4/1] การร่วมมือสถาปนาสุโขทัย'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พ่อขุนรามคำแหงมหาราชทรงอาราธนาพระสงฆ์จากเมืองใดเข้ามาเผยแผ่พระพุทธศาสนานิกายเถรวาทลังกาวงศ์ในสุโขทัย', '["เมืองนครศรีธรรมราช","เมืองเชียงใหม่","เมืองละโว้","เมืองพะเยา"]'::jsonb, '0'::jsonb, 'พ่อขุนรามคำแหงทรงอัญเชิญพระมหาเถรและพระสงฆ์จากเมืองนครศรีธรรมราชซึ่งมีความรู้เชี่ยวชาญพระไตรปิฎกขึ้นมาเผยแผ่ธรรม ณ สุโขทัย', 'medium', '[ส 4.3 ป.4/2] การรับพระพุทธศาสนานิกายเถรวาทลังกาวงศ์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', '''สรีดภงส์'' หรือเขื่อนดินโบราณในสมัยสุโขทัย มีประโยชน์สำคัญที่สุดอย่างไร', '["กักเก็บน้ำจากภูเขาและผันน้ำเข้าสู่คูเมืองและตระพังเพื่อใช้ในการอุปโภคบริโภค","เป็นกำแพงป้องกันข้าศึก","ใช้เป็นลานประกอบพิธีกรรม","ใช้เลี้ยงสัตว์ป่า"]'::jsonb, '0'::jsonb, 'สรีดภงส์ คือทำนบกั้นน้ำหรือเขื่อนดินที่สร้างขึ้นเพื่อกักเก็บน้ำฝนที่ไหลลงจากเขาหลวง แล้วส่งผ่านคูคลองเข้าสู่ตัวเมืองสุโขทัย', 'medium', '[ส 4.3 ป.4/2] ภูมิปัญญาชลประทานสุโขทัย (สรีดภงส์)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ในสมัยสุโขทัยตอนปลาย พระมหาธรรมราชาที่ 1 (ลิไทย) ทรงปรับเปลี่ยนรูปแบบการปกครองมาใช้หลักธรรมใดในการปกครองบ้านเมือง', '["ทศพิธราชธรรม (การปกครองแบบธรรมราชา)","เทวราชา (สมมติเทพ)","เผด็จการทหาร","กฎหมายตราสามดวง"]'::jsonb, '0'::jsonb, 'พระมหาธรรมราชาที่ 1 ทรงนำหลักทศพิธราชธรรม (ธรรมะ 10 ประการของกษัตริย์) มาใช้เป็นแนวทางในการปกครอง เรียกว่า ''ธรรมราชา''', 'medium', '[ส 4.3 ป.4/2] การปกครองแบบธรรมราชา'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เตาเผาเครื่องปั้นดินเผาโบราณในสมัยสุโขทัย มีชื่อเรียกเฉพาะว่าอย่างไร', '["เตาทุเรียง","เตาอั้งโล่","เตาหลอมโลหะ","เตาผิง"]'::jsonb, '0'::jsonb, 'เตาเผาเคลือบเครื่องสังคโลกในสมัยสุโขทัยและศรีสัชนาลัย เรียกว่า ''เตาทุเรียง'' ซึ่งก่อด้วยอิฐและให้ความร้อนสูง', 'medium', '[ส 4.3 ป.4/2] เตาเผาเครื่องสังคโลก (เตาทุเรียง)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พระมหากษัตริย์ 3 พระองค์ที่เป็นพระสหายร่วมสาบานและช่วยกันวางผังสร้างเมืองเชียงใหม่ ได้แก่พระองค์ใดบ้าง', '["พ่อขุนรามคำแหง, พญามังราย, พญางำเมือง","พ่อขุนศรีอินทราทิตย์, พ่อขุนผาเมือง, พญามังราย","สมเด็จพระนเรศวร, สมเด็จพระเอกาทศรถ, พ่อขุนรามคำแหง","พระเจ้าอู่ทอง, ขุนหลวงพะงั่ว, พ่อขุนรามคำแหง"]'::jsonb, '0'::jsonb, 'สามกษัตริย์ผู้เป็นมิตรรักใคร่กลมเกลียว คือ พญามังราย (ผู้ครองล้านนา), พ่อขุนรามคำแหง (สุโขทัย), และพญางำเมือง (พะเยา)', 'medium', '[ส 4.3 ป.4/3] มิตรภาพสามกษัตริย์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ท้าวเทพกระษัตรีและท้าวศรีสุนทร (ย่าจัน-ย่ามุก) มีบทบาทสำคัญในการปกป้องเมืองใดจากการรุกรานของข้าศึก', '["เมืองถลาง (จังหวัดภูเก็ตในปัจจุบัน)","เมืองนครศรีธรรมราช","เมืองสงขลา","เมืองปัตตานี"]'::jsonb, '0'::jsonb, 'ท่านผู้หญิงจันและคุณมุก รวบรวมกำลังพลชาวเมืองถลางสู้รบกับกองทัพพม่าอย่างกล้าหาญจนได้รับชัยชนะในสงครามเก้าทัพ', 'medium', '[ส 4.3 ป.4/3] วีรสตรีไทย (ท้าวเทพกระษัตรีและท้าวศรีสุนทร)'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เหตุใดเครื่องมือเครื่องใช้ที่ทำจาก ''เหล็ก'' จึงมีประสิทธิภาพมากกว่าเครื่องมือสำริด', '["เพราะเหล็กมีความแข็งแกร่ง ทนทาน และหาแร่ได้แพร่หลายมากกว่า","เพราะเหล็กมีน้ำหนักเบากว่า","เพราะเหล็กไม่มีวันเกิดสนิม","เพราะเหล็กมีสีสันสวยงามกว่า"]'::jsonb, '0'::jsonb, 'เหล็กเป็นโลหะที่มีความแข็ง คม และทนทานมากกว่าสำริด ทำให้การตัดต้นไม้ ถากดิน และการทำอาวุธมีประสิทธิภาพสูงขึ้นมาก', 'medium', '[ส 4.1 ป.4/2] ยุคเหล็ก'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'อาณาจักรโคตรบูรณ์ตั้งอยู่ริมสองฝั่งแม่น้ำโขงแถบภาคอีสาน โบราณสถานสำคัญคู่บ้านคู่เมืองคือที่ใด', '["พระธาตุพนม (จังหวัดนครพนม)","ปราสาทหินพิมาย","พระธาตุดอยสุเทพ","พระปฐมเจดีย์"]'::jsonb, '0'::jsonb, 'อาณาจักรโคตรบูรณ์มีศูนย์กลางแถบลุ่มน้ำโขง โบราณสถานสำคัญอันศักดิ์สิทธิ์คือ พระธาตุพนม ในจังหวัดนครพนม', 'medium', '[ส 4.2 ป.4/2] อาณาจักรโคตรบูรณ์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ในสมัยพ่อขุนรามคำแหงมหาราช ทรงแขวนกระดิ่งไว้ที่ประตูเมืองเพื่อประโยชน์ใด', '["เพื่อให้ราษฎรที่มีความเดือดร้อนมาสั่นกระดิ่งเพื่อทูลร้องทุกข์โดยตรง","เพื่อบอกเวลาเปิด-ปิดประตูเมือง","เพื่อใช้เตือนภัยเมื่อมีข้าศึกมา","เพื่อความสวยงาม"]'::jsonb, '0'::jsonb, 'การแขวนกระดิ่งที่ประตูเมืองเป็นการเปิดโอกาสให้ราษฎรที่มีคดีความหรือเดือดร้อนมาสั่นกระดิ่ง พระองค์จะเสด็จออกไปตัดสินด้วยความยุติธรรม', 'medium', '[ส 4.3 ป.4/2] สัญลักษณ์กระดิ่งร้องทุกข์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เมื่อพบหลักฐานทางประวัติศาสตร์ ขั้นตอนแรกในการตรวจสอบความน่าเชื่อถือคือข้อใด', '["ตรวจสอบว่าใครเป็นผู้สร้าง สร้างขึ้นเมื่อใด และมีจุดประสงค์อะไร","เชื่อทันทีว่าเป็นความจริงทั้งหมด","นำไปลงขายในตลาดโบราณวัตถุ","ทิ้งไปถ้ามีตัวหนังสือเลือนราง"]'::jsonb, '0'::jsonb, 'การวิพากษ์หลักฐานภายนอก (External Criticism) ต้องตรวจสอบผู้บันทึก วันเวลาที่สร้าง และความแท้จริงของหลักฐานก่อนเสมอ', 'medium', '[ส 4.1 ป.4/3] การประเมินความน่าเชื่อถือของหลักฐาน'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'คำว่า ''ตระพัง'' ในสมัยสุโขทัย หมายถึงสิ่งใด', '["สระน้ำหรืออ่างเก็บน้ำขนาดใหญ่ภายในวัดและเมือง","กำแพงเมืองโบราณ","เจดีย์ทรงพุ่มข้าวบิณฑ์","ตลาดค้าขายผ้า"]'::jsonb, '0'::jsonb, 'ตระพัง เป็นภาษาเขมรโบราณ หมายถึง สระน้ำหรือบ่อน้ำขุดขนาดใหญ่ เช่น ตระพังเงิน ตระพังทอง ตระพังตระกวน ในเมืองสุโขทัย', 'medium', '[ส 4.3 ป.4/2] ตระพังในสมัยสุโขทัย'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เจดีย์ทรงพุ่มข้าวบิณฑ์ (หรือทรงดอกบัวตูม) เป็นเอกลักษณ์ทางสถาปัตยกรรมเฉพาะของอาณาจักรใด', '["อาณาจักรสุโขทัย","อาณาจักรอยุธยา","อาณาจักรธนบุรี","อาณาจักรรัตนโกสินทร์"]'::jsonb, '0'::jsonb, 'เจดีย์ทรงพุ่มข้าวบิณฑ์หรือดอกบัวตูม เป็นศิลปะสุโขทัยแท้บริสุทธิ์ สะท้อนเอกลักษณ์ทางพุทธศิลป์ที่งดงามของสุโขทัย', 'medium', '[ส 4.3 ป.4/2] เจดีย์ทรงพุ่มข้าวบิณฑ์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เหตุใดมนุษย์ในยุคหินเก่าจึงต้องอาศัยอยู่ตามถ้ำและเพิงผา', '["เพื่อหลบภัยจากสัตว์ร้ายและป้องกันแดดฝน พายุ อากาศหนาว","เพื่อความสวยงามทางธรรมชาติ","เพราะกลัวเพื่อนบ้าน","เพราะต้องการอยู่ใกล้น้ำตก"]'::jsonb, '0'::jsonb, 'มนุษย์ยุคหินเก่ายังไม่รู้จักสร้างบ้านเรือนถาวร จึงอาศัยถ้ำและเพิงผาตามธรรมชาติเป็นที่กำบังแดด ลม ฝน และสัตว์ป่าอันตราย', 'medium', '[ส 4.1 ป.4/2] สภาพความเป็นอยู่ของมนุษย์ยุคก่อนประวัติศาสตร์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ใครเป็นผู้ค้นพบศิลาจารึกหลักที่ 1 (จารึกพ่อขุนรามคำแหง) ณ เนินปราสาท เมืองเก่าสุโขทัย', '["พระบาทสมเด็จพระจอมเกล้าเจ้าอยู่หัว (รัชกาลที่ 4 ขณะทรงผนวช)","พระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว (รัชกาลที่ 5)","สมเด็จพระบรมวงศ์เธอ กรมพระยาดำรงราชานุภาพ","พ่อขุนศรีอินทราทิตย์"]'::jsonb, '0'::jsonb, 'พระบาทสมเด็จพระจอมเกล้าเจ้าอยู่หัว (รัชกาลที่ 4) เมื่อครั้งยังทรงพระยศเป็นเจ้าฟ้ามงกุฎและทรงผนวช เสด็จธุดงค์ไปพบศิลาจารึกหลักที่ 1 เมื่อ พ.ศ. 2376', 'medium', '[ส 4.3 ป.4/1] ศิลาจารึกหลักที่ 1'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พ่อขุนรามคำแหงมหาราชทรงประดิษฐ์อักษรไทยขึ้นใน พ.ศ. 1826 เหตุการณ์นี้ตรงกับ ''พุทธศตวรรษ'' และ ''คริสต์ศตวรรษ'' ใดตามลำดับ (เกณฑ์ พ.ศ. - 543 = ค.ศ.)', '["พุทธศตวรรษที่ 19 และ คริสต์ศตวรรษที่ 13","พุทธศตวรรษที่ 18 และ คริสต์ศตวรรษที่ 14","พุทธศตวรรษที่ 19 และ คริสต์ศตวรรษที่ 12","พุทธศตวรรษที่ 18 และ คริสต์ศตวรรษที่ 13"]'::jsonb, '0'::jsonb, 'พ.ศ. 1826 อยู่ในช่วง พ.ศ. 1801-1900 จึงเป็นพุทธศตวรรษที่ 19 เมื่อแปลงเป็น ค.ศ.: 1826 - 543 = ค.ศ. 1283 อยู่ในช่วง ค.ศ. 1201-1300 จึงเป็นคริสต์ศตวรรษที่ 13', 'hard', '[ส 4.1 ป.4/1] การคำนวณและเปรียบเทียบยุคสมัยศักราช'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'หากต้องการศึกษาเรื่องราวชีวิตความเป็นอยู่และเศรษฐกิจของชาวสุโขทัย หลักฐานข้อใดมีความน่าเชื่อถือและให้ข้อมูลรอบด้านที่สุด', '["ศิลาจารึกสุโขทัยหลักที่ 1 ควบคู่กับการสำรวจโบราณสถานและเศษเครื่องสังคโลกในพื้นที่จริง","ภาพยนตร์ประวัติศาสตร์ที่ฉายในโรงภาพยนตร์","เรื่องเล่าและตำนานพื้นบ้านที่เล่าสืบต่อกันมาโดยไม่มีบันทึก","นวนิยายย้อนยุคที่แต่งขึ้นใหม่"]'::jsonb, '0'::jsonb, 'การศึกษาประวัติศาสตร์ที่น่าเชื่อถือต้องอาศัยหลักฐานชั้นต้นที่เป็นลายลักษณ์อักษร (ศิลาจารึก) ร่วมกับหลักฐานทางโบราณคดีที่เป็นวัตถุจริง (โบราณสถาน, เครื่องสังคโลก)', 'hard', '[ส 4.1 ป.4/3] การเปรียบเทียบคุณค่าของหลักฐานทางประวัติศาสตร์'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ปัจจัยทางภูมิศาสตร์ข้อใดส่งผลให้อาณาจักรศรีวิชัยและอาณาจักรตามพรลิงก์รุ่งเรืองด้านการค้าทางทะเลอย่างยิ่ง', '["ตั้งอยู่บนคาบสมุทรที่เป็นเส้นทางผ่านของเรือสำเภาและจุดแวะพักหลบลมมรสุมระหว่างจีนกับอินเดีย","มีพื้นที่ปลูกข้าวสาลีขนาดใหญ่ที่สุดในเอเชีย","มีแร่ทองคำและเพชรพลอยมากที่สุดในโลก","มีเทือกเขาสูงปิดล้อมข้าศึกบุกไม่ได้"]'::jsonb, '0'::jsonb, 'คาบสมุทรไทย-มลายูเป็นเส้นทางเดินเรือค้าขายสำคัญเชื่อมมหาสมุทรอินเดียและแปซิฟิก เรือสินค้าต้องแวะพักถ่ายสินค้าและหลบลมมรสุมตามเมืองท่าเหล่านี้', 'hard', '[ส 4.2 ป.4/2] การวิเคราะห์ปัจจัยความรุ่งเรืองของอาณาจักรโบราณ'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เพราะเหตุใดรูปแบบการปกครองแบบ ''พ่อปกครองลูก'' จึงเหมาะสมกับสุโขทัยในยุคต้น แต่ไม่สามารถนำมาใช้กับอาณาจักรที่มีขนาดใหญ่ในยุคหลังได้', '["เพราะในยุคต้นสุโขทัยมีประชากรน้อยและอาณาเขตไม่กว้างขวาง กษัตริย์จึงดูแลราษฎรได้อย่างทั่วถึงและใกล้ชิด","เพราะกษัตริย์ในยุคหลังไม่รักราษฎร","เพราะราษฎรในยุคหลังไม่ต้องการพบกษัตริย์","เพราะไม่มีกระดิ่งขนาดใหญ่พอที่จะได้ยินทั้งอาณาจักร"]'::jsonb, '0'::jsonb, 'การปกครองแบบพ่อปกครองลูกเหมาะกับชุมชนหรือนครรัฐขนาดเล็กที่มีประชากรไม่มาก เมื่ออาณาจักรขยายกว้างใหญ่ขึ้นจึงต้องใช้ระบบราชการและกฎเกณฑ์ที่รัดกุมขึ้น', 'hard', '[ส 4.3 ป.4/2] การวิเคราะห์ความสัมพันธ์ระหว่างการปกครองกับเสถียรภาพบ้านเมือง'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'เมืองสุโขทัยไม่ได้ตั้งอยู่ติดริมแม่น้ำใหญ่ (แม่น้ำยมอยู่ห่างออกไป) ชาวสุโขทัยแก้ปัญหาการขาดแคลนน้ำด้วยภูมิปัญญาใดอย่างเป็นระบบ', '["สร้างทำนบกั้นน้ำ (สรีดภงส์) รับน้ำจากเขาหลวง ผันน้ำผ่านท่อดินเผาและคูคลองลงสู่ตระพังทั่วเมือง","ขุดอุโมงค์ใต้ดินเชื่อมแม่น้ำเจ้าพระยา","ใช้วิธีนำเข้ากระบอกน้ำดื่มจากเมืองมอญ","รอน้ำฝนเพียงอย่างเดียวโดยไม่มีการกักเก็บ"]'::jsonb, '0'::jsonb, 'ชาวสุโขทัยมีภูมิปัญญาการจัดการน้ำขั้นสูง โดยสร้างสรีดภงส์กักเก็บน้ำจากเทือกเขาหลวง และส่งน้ำผ่านคูคลองเข้าสู่ตระพัง (สระน้ำ) ประจำวัดและเมือง ทำให้มีน้ำใช้ตลอดปี', 'hard', '[ส 4.3 ป.4/2] การวิเคราะห์ระบบชลประทานสุโขทัย'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'พระมหาธรรมราชาที่ 1 (ลิไทย) ทรงใช้ ''วรรณกรรมไตรภูมิพระร่วง'' เป็นเครื่องมือสำคัญในการรักษาความสงบสุขของบ้านเมืองอย่างไร', '["ใช้หลักบาปบุญคุณโทษในพุทธศาสนาปลูกฝังให้ราษฎรละเว้นความชั่ว เกรงกลัวนรก และประพฤติความดีเพื่อไปสวรรค์","ใช้เป็นกฎหมายลงโทษประหารชีวิตราษฎร","ใช้สำหรับเกณฑ์ทหารไปทำศึกสงคราม","ใช้บังคับเก็บภาษีอากรจากคนรวย"]'::jsonb, '0'::jsonb, 'ไตรภูมิพระร่วงมุ่งอธิบายผลของกรรมดีและกรรมชั่ว ทำให้ราษฎรมีจิตสำนึกทางศีลธรรม มีความเกรงกลัวและละอายต่อบาป ช่วยให้สังคมสงบสุขโดยไม่ต้องใช้กำลังบังคับ', 'hard', '[ส 4.3 ป.4/3] วรรณกรรมไตรภูมิพระร่วงกับการปกครอง'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'การเปลี่ยนผ่านจาก ''ยุคสำริด'' สู่ ''ยุคเหล็ก'' ส่งผลต่อการเปลี่ยนแปลงทางสังคมของมนุษย์โบราณในดินแดนไทยอย่างไรมากที่สุด', '["เครื่องมือเหล็กทำให้การหักร้างถางพงและขยายพื้นที่เกษตรกรรมทำได้รวดเร็ว ชุมชนขยายตัวเป็นบ้านเมืองขนาดใหญ่ขึ้น","มนุษย์เลิกทำการเกษตรแล้วหันมาสร้างโรงงาน","ทำให้ประชากรลดลงเพราะแร่เหล็กหายาก","ทำให้มนุษย์เลิกนับถือศาสนา"]'::jsonb, '0'::jsonb, 'เหล็กมีความแข็งแกร่งกว่าสำริด นำมาทำผาลไถ ขวาน และเสียม ทำให้การเพาะปลูกขยายตัว ผลผลิตเพิ่มขึ้น ประชากรเพิ่ม และพัฒนาสู่สังคมระดับเมือง', 'hard', '[ส 4.2 ป.4/1] การวิเคราะห์วิวัฒนาการเทคโนโลยีโลหกรรม'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'การส่งคณะราชทูตสุโขทัยไปยังราชสำนักจีนในสมัยราชวงศ์หยวน มีจุดประสงค์หลักเพื่อผลประโยชน์ข้อใด', '["ประโยชน์ทางการค้าในระบบบรรณาการและการนำช่างปั้นชาวจีนมาถ่ายทอดเทคโนโลยีการทำเครื่องสังคโลก","การขอกำลังทหารจีนมาช่วยรบกับอยุธยา","การอพยพประชากรสุโขทัยไปอยู่ประเทศจีน","การเปลี่ยนศาสนาไปนับถือลัทธิขงจื๊อ"]'::jsonb, '0'::jsonb, 'การเจริญสัมพันธไมตรีกับจีนช่วยให้สุโขทัยทำการค้าขายในระบบบรรณาการอย่างราบรื่น และได้ช่างผู้เชี่ยวชาญจากจีนมาช่วยพัฒนาเตาเผาและเครื่องสังคโลกจนได้มาตรฐานส่งออก', 'hard', '[ส 4.3 ป.4/2] ความสัมพันธ์ระหว่างสุโขทัยกับต่างประเทศ'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'ข้อความในศิลาจารึกสุโขทัย ''เมื่อชั่วพ่อกู กูบำเรอแก่พ่อกู กูบำเรอแก่แม่กู กูได้ตัวเนื้อตัวปลา กูเอามาแก่พ่อกู'' แสดงถึงค่านิยมใดที่เด่นชัดที่สุดในสังคมไทย', '["ความกตัญญูกตเวทิตาและการดูแลเอาใจใส่บุพการี","การแข่งขันล่าสัตว์ในป่า","การแบ่งแยกหน้าที่ระหว่างชายและหญิง","การบังคับให้เด็กต้องทำงานหนัก"]'::jsonb, '0'::jsonb, 'ข้อความนี้พ่อขุนรามคำแหงทรงเล่าถึงวัยเยาว์ สะท้อนความกตัญญู ความเคารพ และการปรนนิบัติดูแลพ่อแม่ ซึ่งเป็นค่านิยมหลักของสังคมไทยมาตั้งแต่โบราณ', 'hard', '[ส 4.3 ป.4/1] ศิลาจารึกกับการสะท้อนสิทธิสตรีและครอบครัว'),
  ('ประวัติศาสตร์', 'ป.4', 'mcq', 'อาณาจักรสุโขทัยในที่สุดได้ถูกผนวกรวมเข้าเป็นส่วนหนึ่งของอาณาจักรใดในประวัติศาสตร์ไทย', '["อาณาจักรอยุธยา","อาณาจักรล้านนา","อาณาจักรธนบุรี","อาณาจักรพม่า"]'::jsonb, '0'::jsonb, 'สุโขทัยค่อยๆ ลดทอนอำนาจลงและกลายเป็นประเทศราชของอยุธยา จนกระทั่งถูกผนวกรวมเข้าเป็นดินแดนส่วนหนึ่งของกรุงศรีอยุธยาอย่างสมบูรณ์ในรัชสมัยสมเด็จพระบรมไตรโลกนาถ', 'hard', '[ส 4.3 ป.4/2] การสิ้นสุดความเป็นอิสระของสุโขทัย');
